 public class MiniActionButton:Button {
  public string Kind="play";
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;float s=Math.Min(Width,Height)/28f;var old=g.Save();g.TranslateTransform((Width-28*s)/2,(Height-28*s)/2);g.ScaleTransform(s,s);Color color=ForeColor;using(var pen=new Pen(color,1.8f))using(var brush=new SolidBrush(color)){if(Kind=="pause"){g.FillRectangle(brush,8,7,4,14);g.FillRectangle(brush,16,7,4,14);}else if(Kind=="play")g.FillPolygon(brush,new[]{new PointF(9,6),new PointF(22,14),new PointF(9,22)});else if(Kind=="rest"){g.DrawRectangle(pen,5,10,14,11);g.DrawArc(pen,16,11,8,8,-90,180);g.DrawLine(pen,8,4,8,7);g.DrawLine(pen,14,4,14,7);}else if(Kind=="undo"){g.DrawArc(pen,7,7,14,14,205,235);g.FillPolygon(brush,new[]{new PointF(5,10),new PointF(12,9),new PointF(8,15)});}else if(Kind=="bulb"){g.DrawEllipse(pen,8,5,12,13);g.DrawLine(pen,11,20,17,20);g.DrawLine(pen,11,23,17,23);g.DrawLine(pen,14,1,14,4);g.DrawLine(pen,4,8,7,9);g.DrawLine(pen,21,9,24,8);}else if(Kind=="lock"||Kind=="unlock"){g.DrawRectangle(pen,7,12,14,11);g.DrawArc(pen,9,4,10,13,Kind=="lock"?180:210,Kind=="lock"?180:130);g.DrawLine(pen,14,16,14,20);}else if(Kind=="close"){g.DrawLine(pen,8,8,20,20);g.DrawLine(pen,20,8,8,20);}else{g.DrawRectangle(pen,6,7,16,14);g.DrawLine(pen,6,11,22,11);}}g.Restore(old);}
 }
 public class RestTicker:Label {
  public bool Scrolling;public float Offset;
  protected override void OnPaint(PaintEventArgs e){if(!Scrolling){base.OnPaint(e);return;}int width=TextRenderer.MeasureText(Text,Font,new Size(Int32.MaxValue,Height),TextFormatFlags.SingleLine|TextFormatFlags.NoPadding).Width;if(width<=Width){base.OnPaint(e);return;}int x=-(int)(Offset%(width+35));TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(x,0,width+10,Height),ForeColor,TextFormatFlags.SingleLine|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding|TextFormatFlags.NoPrefix);TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(x+width+35,0,width+10,Height),ForeColor,TextFormatFlags.SingleLine|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding|TextFormatFlags.NoPrefix);}
 }
