  public void SetPreferences(int dim,string text){dimPercent=Math.Max(0,Math.Min(100,dim));restText=String.IsNullOrWhiteSpace(text)?"( ˘ω˘ )":text;} public void SetStages(IEnumerable<Stage> value){pathStages=value==null?new List<Stage>():value.ToList();motion.Invalidate();ConfigureAnimation();} Color Fade(Color color){double a=locked?dimPercent/100.0:1;return Color.FromArgb((int)(color.R*a+BackColor.R*(1-a)),(int)(color.G*a+BackColor.G*(1-a)),(int)(color.B*a+BackColor.B*(1-a)));} void ApplyLock(){closeButton.Visible=!locked;if(!locked){hoverTimer.Enabled=false;if(clickThrough){SetClickThrough(false);clickThrough=false;}FadeTo(baseOpacity);}else{FadeTo(1);hoverTimer.Enabled=true;}toggle.Enabled=!locked&&task.Text!="未选择任务";rest.Enabled=!locked&&rest.Visible;open.Enabled=!locked;distract.Enabled=!locked&&distract.Visible;withdraw.Enabled=!locked&&withdraw.Visible;stageCheck.Enabled=!locked&&hasStage;lockButton.Kind=locked?"lock":"unlock";lockButton.Invalidate();tips.Active=!locked;task.AutoEllipsis=!locked;task.Font=UI.Font(locked?10:9,true);countdown.Font=UI.Font(locked?20:17,true);elapsed.Font=UI.Font(locked?10.5f:8.5f,locked);task.ForeColor=Fade(UI.Ink);phase.ForeColor=Fade(UI.Muted);toggle.ForeColor=rest.ForeColor=open.ForeColor=distract.ForeColor=withdraw.ForeColor=Fade(UI.Green);elapsed.ForeColor=hasStage||current==Phase.Break?UI.Ink:Fade(UI.Ink);stageCheck.Visible=hasStage&&!locked;motion.Visible=!lowStimulus;toggle.Invalidate();rest.Invalidate();open.Invalidate();distract.Invalidate();withdraw.Invalidate();elapsed.Invalidate();tips.SetToolTip(lockButton,locked?"已锁定，点击解锁":"锁定：禁用操作与拖动");} void Theme(Control c,Color color){c.BackColor=color;foreach(Control child in c.Controls)Theme(child,color);}
